package com.marinainsaurralde.plango.ui;
import android.view.*;import android.widget.TextView;import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import com.marinainsaurralde.plango.R;import com.marinainsaurralde.plango.model.ConsultaHistorial;import java.text.SimpleDateFormat;import java.util.*;
public final class ConsultaAdapter extends RecyclerView.Adapter<ConsultaAdapter.Holder>{public interface Listener{void onClick(ConsultaHistorial c);}private final List<ConsultaHistorial>items=new ArrayList<>();private final Listener listener;public ConsultaAdapter(Listener l){listener=l;}public void setItems(List<ConsultaHistorial>v){items.clear();items.addAll(v);notifyDataSetChanged();}@NonNull public Holder onCreateViewHolder(@NonNull ViewGroup p,int v){return new Holder(LayoutInflater.from(p.getContext()).inflate(R.layout.item_consulta,p,false));}public void onBindViewHolder(@NonNull Holder h,int p){ConsultaHistorial c=items.get(p);SimpleDateFormat f=new SimpleDateFormat("d MMM yyyy, HH:mm",new Locale("es","ES"));f.setTimeZone(TimeZone.getTimeZone("Europe/Madrid"));h.date.setText(c.fechaConsulta==null?"—":f.format(c.fechaConsulta));h.total.setText(h.itemView.getContext().getString(R.string.history_total,c.totalEventos));h.counts.setText(h.itemView.getContext().getString(R.string.history_counts,c.totalGratuitos,c.totalPago,c.totalSinInformacion));h.origin.setText("manual".equals(c.origen)?R.string.origin_manual:R.string.origin_automatic);h.itemView.setOnClickListener(v->listener.onClick(c));}public int getItemCount(){return items.size();}static final class Holder extends RecyclerView.ViewHolder{TextView date,total,counts,origin;Holder(View v){super(v);date=v.findViewById(R.id.textQueryDate);total=v.findViewById(R.id.textQueryTotal);counts=v.findViewById(R.id.textQueryCounts);origin=v.findViewById(R.id.textQueryOrigin);}}}
